/**
 * Live voice calls: PushKit registration and CallKit reporting in AppDelegate.
 *
 * `ios/` is generated by prebuild, so this edits the generated Swift
 * AppDelegate and its bridging header rather than committed native code.
 *
 * Why native: iOS terminates an app that receives a VoIP push and does not
 * report a call to CallKit before the PushKit handler returns — and on a cold
 * launch JavaScript is not loaded yet. So every push is reported here, at once,
 * with the payload's `callId` as the CallKit UUID and `summary` as the caller.
 * JavaScript (`src/voice/callkit.ts`) only reacts to what CallKit reports back.
 *
 * Swift calls the two ObjC libraries through the bridging header (no ObjC++
 * helper file is needed, so the Xcode project is not touched).
 */
const { withDangerousMod } = require("expo/config-plugins");
const fs = require("node:fs");
const path = require("node:path");

const MARK = "// pew2-voice";

const IMPORTS = `${MARK}
#import <RNCallKeep/RNCallKeep.h>
#import <RNVoipPushNotification/RNVoipPushNotificationManager.h>
`;

const LAUNCH = `    ${MARK}: CallKit must be configured before a push can be reported, and
    // PushKit registered at launch so a push that cold-starts the app lands here.
    RNCallKeep.setup(["appName": "pew2", "supportsVideo": false, "includesCallsInRecents": false])
    RNVoipPushNotificationManager.voipRegistration()

`;

const DELEGATE = `
${MARK}
extension AppDelegate: PKPushRegistryDelegate {
  public func pushRegistry(_ registry: PKPushRegistry, didUpdate credentials: PKPushCredentials, for type: PKPushType) {
    RNVoipPushNotificationManager.didUpdate(credentials, forType: type.rawValue)
  }

  public func pushRegistry(_ registry: PKPushRegistry, didInvalidatePushTokenFor type: PKPushType) {}

  public func pushRegistry(
    _ registry: PKPushRegistry,
    didReceiveIncomingPushWith payload: PKPushPayload,
    for type: PKPushType,
    completion: @escaping () -> Void
  ) {
    var fields = payload.dictionaryPayload
    for key in ["voice", "data", "payload"] {
      if fields["callId"] == nil, let inner = fields[key] as? [AnyHashable: Any], inner["callId"] != nil {
        fields = inner
      }
    }
    let rawId = (fields["callId"] as? String).flatMap { UUID(uuidString: $0) }
    // A call must be reported even for a malformed push, or iOS kills the app;
    // a bad id gets a fresh UUID and is ended straight away.
    let uuid = (rawId ?? UUID()).uuidString.lowercased()
    var caller = (fields["summary"] as? String) ?? ""
    if caller.isEmpty { caller = "pew2" }
    if caller.count > 60 { caller = String(caller.prefix(59)) + "…" }

    RNCallKeep.reportNewIncomingCall(
      uuid,
      handle: "pew2",
      handleType: "generic",
      hasVideo: false,
      localizedCallerName: caller,
      supportsHolding: false,
      supportsDTMF: false,
      supportsGrouping: false,
      supportsUngrouping: false,
      fromPushKit: true,
      payload: fields as? [String: Any],
      withCompletionHandler: nil
    )
    if rawId == nil { RNCallKeep.endCall(withUUID: uuid, reason: 1) }
    RNVoipPushNotificationManager.didReceiveIncomingPush(with: payload, forType: type.rawValue)
    completion()
  }
}
`;

function patchAppDelegate(source) {
  if (source.includes(MARK)) return source;
  let out = source;
  if (!out.includes("import PushKit")) out = out.replace("import Expo\n", "import Expo\nimport PushKit\n");
  const anchor = "    return super.application(application, didFinishLaunchingWithOptions: launchOptions)";
  if (!out.includes(anchor)) throw new Error("withVoiceCall: AppDelegate launch anchor not found; update the plugin for this Expo SDK.");
  out = out.replace(anchor, LAUNCH + anchor);
  return out + DELEGATE;
}

const withVoiceCall = (config) =>
  withDangerousMod(config, [
    "ios",
    (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, cfg.modRequest.projectName);
      const delegatePath = path.join(dir, "AppDelegate.swift");
      fs.writeFileSync(delegatePath, patchAppDelegate(fs.readFileSync(delegatePath, "utf8")));
      const header = fs.readdirSync(dir).find((f) => f.endsWith("-Bridging-Header.h"));
      if (!header) throw new Error("withVoiceCall: no bridging header in the iOS project.");
      const headerPath = path.join(dir, header);
      const text = fs.readFileSync(headerPath, "utf8");
      if (!text.includes(MARK)) fs.writeFileSync(headerPath, `${text}\n${IMPORTS}`);
      return cfg;
    },
  ]);

module.exports = withVoiceCall;
module.exports.patchAppDelegate = patchAppDelegate;
